let muscleBodyChart=null,summaryBodyChart=null;
function muscleTargets(name){
 const s=String(name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const out=[];
 if(/supino|crucifixo|peck|chest press|flexao de braco/.test(s))out.push('Chest');
 if(/remada|puxada|pulldown|barra fixa|dorsal|costas/.test(s))out.push('Back');
 if(/desenvolvimento|elevacao lateral|elevacao frontal|ombro/.test(s))out.push('Shoulders');
 if(/rosca|biceps|curl|triceps|testa|corda/.test(s))out.push('Arms');
 if(/abdominal|prancha|crunch|infra|supra|obliquo/.test(s))out.push('Abdominals');
 if(/agachamento|leg press|extensora|passada|avanco|squat|stiff|flexora|mesa flexora|levantamento terra|deadlift|panturrilha|gemeos|glute|elevacao pelvica|hip thrust|coice|kickback|abdutora/.test(s))out.push('Legs');
 return [...new Set(out)];
}
function renderMuscleAtlas(exercises){
 const host=$('muscle-map');if(!host)return;
 const sex=user?.user_metadata?.sex==='female'?'female':'male';
 const counts={Chest:0,Back:0,Shoulders:0,Arms:0,Abdominals:0,Legs:0};
 for(const ex of exercises||[])for(const group of muscleTargets(ex.exercise_name))counts[group]++;
 const max=Math.max(1,...Object.values(counts)),state={};
 for(const muscle of MUSCLE_MAP){const value=counts[muscle.group]||0;if(value)state[muscle.id]={intensity:Math.min(10,Math.max(1,Math.round(value/max*10))),selected:false};}
 host.dataset.sex=sex; host.innerHTML='<div id="muscle-atlas" class="muscle-atlas" aria-label="Mapa anatômico dos músculos, frente e costas"></div>';
 if(muscleBodyChart){try{muscleBodyChart.destroy()}catch(e){}muscleBodyChart=null}
 muscleBodyChart=new BodyChart($('muscle-atlas'),{view:ViewSide.BOTH,bodyState:state,showViewLabel:true,interactive:false,intensityColor:value=>value===0?'#D9DEDC':value<4?'#B7E6C6':value<7?'#55C982':'#168B57',labels:{chart:()=>'Mapa muscular',viewLabel:view=>view===ViewSide.FRONT?'Frente':'Costas',regionName:muscle=>muscle.name,intensity:value=>'Intensidade '+value}});
 const names={Chest:'Peito',Back:'Costas',Shoulders:'Ombros',Arms:'Braços',Abdominals:'Abdômen',Legs:'Pernas'};
 const sorted=Object.keys(counts).filter(k=>counts[k]>0).sort((a,b)=>counts[b]-counts[a]);
 $('muscle-legend').innerHTML=sorted.length?sorted.map(k=>'<span><i style="background:'+(counts[k]/max>.66?'#168B57':counts[k]/max>.33?'#55C982':'#B7E6C6')+'"></i>'+names[k]+' · '+counts[k]+'</span>').join(''):'<span>Registre treinos para visualizar os músculos trabalhados.</span>';
}
async function renderTrainingInsights(){
 const host=$('training-insights');if(!host||!user)return;
 try{
  const since=new Date();since.setDate(since.getDate()-28);
  const {data:sessions,error}=await supabase.from('fit_workout_sessions').select('id,started_at,ended_at').eq('user_id',user.id).not('ended_at','is',null).gte('started_at',since.toISOString()).order('started_at',{ascending:false}).limit(500);
  if(error)throw error;
  const all=(sessions||[]).filter(session=>(new Date(session.ended_at).getTime()-new Date(session.started_at).getTime())>=120000),ids=all.map(x=>x.id);let exercises=[],sets=[];
  if(ids.length){
   const {data:exRows,error:ee}=await supabase.from('fit_workout_exercises').select('id,session_id,exercise_name').in('session_id',ids);if(ee)throw ee;exercises=exRows||[];
   const exIds=exercises.map(x=>x.id);if(exIds.length){const {data:setRows,error:se}=await supabase.from('fit_workout_sets').select('id,exercise_id,completed').in('exercise_id',exIds);if(se)throw se;sets=setRows||[]}
  }
  const setsByExercise={},exercisesBySession={};for(const st of sets)(setsByExercise[st.exercise_id]??=[]).push(st);for(const ex of exercises)(exercisesBySession[ex.session_id]??=[]).push(ex);
  const sessionRates=all.map(session=>{const list=exercisesBySession[session.id]||[];if(!list.length)return 0;const rates=list.map(ex=>{const ss=setsByExercise[ex.id]||[];return ss.length?ss.filter(x=>x.completed).length/ss.length:0});return rates.reduce((a,b)=>a+b,0)/rates.length});
  const heat=sessionRates.length?Math.round(sessionRates.reduce((a,b)=>a+b,0)/sessionRates.length*100):0;
  const doneExercises=exercises.filter(ex=>(setsByExercise[ex.id]||[]).some(st=>st.completed));
  const status=heat>=85?'Pegando fogo! 🔥':heat>=55?'Quente!':heat>=25?'Aquecendo…':'Começando a esquentar';
  const tube=$('frequency-thermometer');tube?.style.setProperty('--heat',heat+'%');const fill=tube?.querySelector('.thermo-fill');if(fill)fill.style.height=heat+'%';const bulb=tube?.querySelector('.thermo-bulb-fill');if(bulb)bulb.style.opacity=String(Math.max(.12,heat/100));
  $('frequency-status').textContent=status;$('frequency-value').textContent=heat+'%';
  $('frequency-detail').textContent='Média de conclusão dos exercícios em '+all.length+' treino(s) nos últimos 28 dias · '+doneExercises.length+' exercício(s) com séries concluídas';
  renderMuscleAtlas(doneExercises);$('muscle-legend').innerHTML='<span><i class="legend-low"></i>Menor foco</span><span><i class="legend-mid"></i>Foco médio</span><span><i class="legend-high"></i>Maior foco</span>';
 }catch(e){$('muscle-map').innerHTML='<p class="muted small">Não foi possível montar seu mapa muscular: '+safe(e.message)+'</p>'}
}
